using System;
using UnityEngine;
using Framework.Grid;
using Framework.CameraSystem;

namespace Game.Tests
{
    /// <summary>
    /// GridCameraFitterの各機能を検証するクラス。
    ///
    /// 表示サイズ計算、ワールド境界取得、
    /// カメラ位置調整、不正値の検証を行う。
    /// </summary>
    public class GridCameraFitterTest : MonoBehaviour
    {
        #region Inspector Fields

        [Header("テスト設定")]

        /// <summary>開始時にテストを実行するか。</summary>
        [SerializeField]
        private bool runTestsOnStart = true;

        [Header("テスト結果")]

        /// <summary>成功したテスト項目数。</summary>
        [SerializeField]
        private int passedCount;

        /// <summary>失敗したテスト項目数。</summary>
        [SerializeField]
        private int failedCount;

        #endregion

        #region Constants

        /// <summary>浮動小数点数の比較許容誤差。</summary>
        private const float Tolerance = 0.001f;

        #endregion

        #region Unity Methods

        /// <summary>シーン開始時の処理。</summary>
        private void Start()
        {
            if (runTestsOnStart)
            {
                RunAllTests();
            }
        }

        #endregion

        #region Test Control Methods

        /// <summary>すべてのテストを実行する。</summary>
        [ContextMenu("テスト/全テストを実行")]
        public void RunAllTests()
        {
            if (!Application.isPlaying)
            {
                return;
            }

            passedCount = 0;
            failedCount = 0;

            GameObject gridObject = null;
            GameObject cameraObject = null;

            Debug.Log(
                "【GridCameraFitter テスト開始】",
                this);

            try
            {
                // テスト専用のGridを生成する。
                gridObject = new GameObject(
                    "CameraTest_Grid");

                UnityEngine.Grid grid =
                    gridObject.AddComponent<UnityEngine.Grid>();

                grid.cellSize = new Vector3(1f, 1f, 0f);
                grid.cellGap = Vector3.zero;

                GridCoordinateConverter converter =
                    gridObject.AddComponent<
                        GridCoordinateConverter>();

                // テスト専用カメラを生成する。
                cameraObject = new GameObject(
                    "CameraTest_Camera");

                cameraObject.SetActive(false);

                Camera testCamera =
                    cameraObject.AddComponent<Camera>();

                // 実際の画面描画には使用しない。
                testCamera.enabled = false;
                testCamera.orthographic = true;
                testCamera.aspect = 16f / 9f;

                testCamera.transform.position =
                    new Vector3(0f, 0f, -10f);

                TestSizeCalculation();
                TestWorldBounds(grid, converter);
                TestCameraFit(testCamera, converter);
                TestInvalidArguments(testCamera, converter);
            }
            catch (Exception exception)
            {
                failedCount++;

                Debug.LogException(exception, this);
            }
            finally
            {
                // テスト専用オブジェクトを破棄する。
                if (cameraObject != null)
                {
                    Destroy(cameraObject);
                }

                if (gridObject != null)
                {
                    Destroy(gridObject);
                }
            }

            string result =
                "【GridCameraFitter テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}";

            if (failedCount == 0)
            {
                Debug.Log(
                    result +
                    "\nすべてのテストに成功しました。",
                    this);
            }
            else
            {
                Debug.LogError(result, this);
            }
        }

        #endregion

        #region Calculation Tests

        /// <summary>
        /// Orthographic Sizeの計算結果を検証する。
        /// </summary>
        private void TestSizeCalculation()
        {
            CheckFloat(
                GridCameraFitter.CalculateOrthographicSize(
                    15f, 11f, 16f / 9f, 1f),
                6.5f,
                "16:9画面の表示サイズ");

            CheckFloat(
                GridCameraFitter.CalculateOrthographicSize(
                    15f, 11f, 4f / 3f, 1f),
                6.5f,
                "4:3画面の表示サイズ");

            CheckFloat(
                GridCameraFitter.CalculateOrthographicSize(
                    15f, 11f, 1f, 1f),
                8.5f,
                "正方形画面の表示サイズ");

            CheckFloat(
                GridCameraFitter.CalculateOrthographicSize(
                    15f, 11f, 9f / 16f, 1f),
                136f / 9f,
                "縦長画面の表示サイズ");

            CheckFloat(
                GridCameraFitter.CalculateOrthographicSize(
                    15f, 11f, 16f / 9f, 0f),
                5.5f,
                "余白なしの表示サイズ");

            CheckFloat(
                GridCameraFitter.CalculateOrthographicSize(
                    15f, 11f, 16f / 9f, 2f),
                7.5f,
                "余白2の表示サイズ");

            CheckFloat(
                GridCameraFitter.CalculateOrthographicSize(
                    30f, 5f, 2f, 1f),
                8f,
                "横長マップの表示サイズ");

            CheckFloat(
                GridCameraFitter.CalculateOrthographicSize(
                    5f, 30f, 2f, 1f),
                16f,
                "縦長マップの表示サイズ");

            CheckFloat(
                GridCameraFitter.CalculateOrthographicSize(
                    0f, 0f, 1f, 0f),
                GridCameraFitter.MinimumOrthographicSize,
                "最小表示サイズの保証");
        }

        #endregion

        #region Bounds Tests

        /// <summary>
        /// グリッドのワールド境界取得を検証する。
        /// </summary>
        /// <param name="grid">テスト対象Grid</param>
        /// <param name="converter">座標変換クラス</param>
        private void TestWorldBounds(
            UnityEngine.Grid grid,
            GridCoordinateConverter converter)
        {
            GridMap<int> map = new GridMap<int>(15, 11);

            Bounds bounds = GridCameraFitter.GetWorldBounds(
                converter,
                map);

            CheckFloat(bounds.size.x, 15f, "境界の横幅");
            CheckFloat(bounds.size.y, 11f, "境界の高さ");

            CheckFloat(
                bounds.center.x, 7.5f,
                "境界の中心X座標");

            CheckFloat(
                bounds.center.y, 5.5f,
                "境界の中心Y座標");

            // Grid原点を移動した場合を検証する。
            grid.transform.position =
                new Vector3(10f, 20f, 0f);

            bounds = GridCameraFitter.GetWorldBounds(
                converter,
                map);

            CheckFloat(
                bounds.center.x, 17.5f,
                "移動したGridの中心X座標");

            CheckFloat(
                bounds.center.y, 25.5f,
                "移動したGridの中心Y座標");

            // セルサイズが1以外の場合を検証する。
            grid.transform.position = Vector3.zero;

            grid.cellSize = new Vector3(2f, 3f, 0f);

            bounds = GridCameraFitter.GetWorldBounds(
                converter,
                map);

            CheckFloat(
                bounds.size.x, 30f,
                "セルサイズ変更後の横幅");

            CheckFloat(
                bounds.size.y, 33f,
                "セルサイズ変更後の高さ");

            // テスト設定を元に戻す。
            grid.cellSize = new Vector3(1f, 1f, 0f);

            // 負のセル座標を含む範囲を検証する。
            bounds = GridCameraFitter.GetWorldBounds(
                converter,
                new RectInt(-5, -3, 10, 6));

            CheckFloat(
                bounds.center.x, 0f,
                "負のセル座標を含む中心X座標");

            CheckFloat(
                bounds.center.y, 0f,
                "負のセル座標を含む中心Y座標");

            // Gridの拡大縮小を検証する。
            grid.transform.localScale =
                new Vector3(2f, 2f, 1f);

            bounds = GridCameraFitter.GetWorldBounds(
                converter,
                map);

            CheckFloat(
                bounds.size.x, 30f,
                "Grid拡大後の横幅");

            CheckFloat(
                bounds.size.y, 22f,
                "Grid拡大後の高さ");

            grid.transform.localScale = Vector3.one;
        }

        #endregion

        #region Camera Fit Tests

        /// <summary>
        /// 実際のカメラ調整処理を検証する。
        /// </summary>
        /// <param name="testCamera">テスト専用カメラ</param>
        /// <param name="converter">座標変換クラス</param>
        private void TestCameraFit(
            Camera testCamera,
            GridCoordinateConverter converter)
        {
            GridMap<int> map = new GridMap<int>(15, 11);

            testCamera.aspect = 16f / 9f;

            GridCameraFitter.Fit(
                testCamera,
                converter,
                map,
                1f);

            CheckFloat(
                testCamera.transform.position.x,
                7.5f,
                "カメラの中心X座標");

            CheckFloat(
                testCamera.transform.position.y,
                5.5f,
                "カメラの中心Y座標");

            CheckFloat(
                testCamera.transform.position.z,
                -10f,
                "カメラのZ座標維持");

            CheckFloat(
                testCamera.orthographicSize,
                6.5f,
                "カメラ表示サイズの反映");

            // 正方形画面へ変更する。
            testCamera.aspect = 1f;

            GridCameraFitter.Fit(
                testCamera,
                converter,
                map,
                1f);

            CheckFloat(
                testCamera.orthographicSize,
                8.5f,
                "画面比率変更後の再調整");

            // より大きなマップへ変更する。
            GridMap<int> largeMap =
                new GridMap<int>(21, 15);

            testCamera.aspect = 16f / 9f;

            GridCameraFitter.Fit(
                testCamera,
                converter,
                largeMap,
                1f);

            CheckFloat(
                testCamera.transform.position.x,
                10.5f,
                "マップ変更後の中心X座標");

            CheckFloat(
                testCamera.transform.position.y,
                7.5f,
                "マップ変更後の中心Y座標");

            CheckFloat(
                testCamera.orthographicSize,
                8.5f,
                "マップ変更後の表示サイズ");

            // カメラの表示範囲を計算する。
            float visibleHeight =
                testCamera.orthographicSize * 2f;

            float visibleWidth =
                visibleHeight * testCamera.aspect;

            Check(
                visibleWidth + Tolerance >= 23f,
                "迷路横幅と余白が画面内に収まる");

            Check(
                visibleHeight + Tolerance >= 17f,
                "迷路高さと余白が画面内に収まる");

            Check(
                Quaternion.Angle(
                    testCamera.transform.rotation,
                    Quaternion.identity) <= Tolerance,
                "カメラ回転の維持");
        }

        #endregion

        #region Validation Tests

        /// <summary>
        /// 不正な引数が拒否されることを検証する。
        /// </summary>
        /// <param name="testCamera">テスト専用カメラ</param>
        /// <param name="converter">座標変換クラス</param>
        private void TestInvalidArguments(
            Camera testCamera,
            GridCoordinateConverter converter)
        {
            CheckThrows<ArgumentOutOfRangeException>(
                () => GridCameraFitter
                    .CalculateOrthographicSize(
                        -1f, 10f, 1f),
                "負の横幅の拒否");

            CheckThrows<ArgumentOutOfRangeException>(
                () => GridCameraFitter
                    .CalculateOrthographicSize(
                        10f, -1f, 1f),
                "負の高さの拒否");

            CheckThrows<ArgumentOutOfRangeException>(
                () => GridCameraFitter
                    .CalculateOrthographicSize(
                        10f, 10f, 0f),
                "無効な画面比率の拒否");

            CheckThrows<ArgumentOutOfRangeException>(
                () => GridCameraFitter
                    .CalculateOrthographicSize(
                        10f, 10f, 1f, -1f),
                "負の余白の拒否");

            CheckThrows<ArgumentOutOfRangeException>(
                () => GridCameraFitter
                    .CalculateOrthographicSize(
                        float.NaN, 10f, 1f),
                "NaNの拒否");

            CheckThrows<ArgumentOutOfRangeException>(
                () => GridCameraFitter
                    .CalculateOrthographicSize(
                        10f, 10f, float.PositiveInfinity),
                "無限大の画面比率の拒否");

            CheckThrows<ArgumentNullException>(
                () => GridCameraFitter.GetWorldBounds(
                    null,
                    new RectInt(0, 0, 10, 10)),
                "未設定の座標変換クラスの拒否");

            CheckThrows<ArgumentException>(
                () => GridCameraFitter.GetWorldBounds(
                    converter,
                    new RectInt(0, 0, 0, 10)),
                "無効なセル範囲の拒否");

            CheckThrows<ArgumentNullException>(
                () => GridCameraFitter.GetWorldBounds<int>(
                    converter,
                    null),
                "未設定のグリッドマップの拒否");

            CheckThrows<ArgumentNullException>(
                () => GridCameraFitter.Fit(
                    null,
                    new Bounds(
                        Vector3.zero,
                        Vector3.one)),
                "未設定のカメラの拒否");

            // Perspective Cameraは対象外とする。
            testCamera.orthographic = false;

            CheckThrows<InvalidOperationException>(
                () => GridCameraFitter.Fit(
                    testCamera,
                    new Bounds(
                        Vector3.zero,
                        Vector3.one)),
                "Perspective Cameraの拒否");

            testCamera.orthographic = true;

            // 傾いたカメラは対象外とする。
            testCamera.transform.rotation =
                Quaternion.Euler(0f, 0f, 30f);

            CheckThrows<InvalidOperationException>(
                () => GridCameraFitter.Fit(
                    testCamera,
                    new Bounds(
                        Vector3.zero,
                        Vector3.one)),
                "回転したカメラの拒否");

            testCamera.transform.rotation =
                Quaternion.identity;
        }

        #endregion

        #region Utility Methods

        /// <summary>
        /// テスト結果を記録する。
        /// </summary>
        /// <param name="condition">成功条件</param>
        /// <param name="testName">テスト項目名</param>
        private void Check(
            bool condition,
            string testName)
        {
            if (condition)
            {
                passedCount++;

                Debug.Log(
                    $"[成功] {testName}",
                    this);
            }
            else
            {
                failedCount++;

                Debug.LogError(
                    $"[失敗] {testName}",
                    this);
            }
        }

        /// <summary>
        /// 浮動小数点数の一致を検証する。
        /// </summary>
        /// <param name="actual">実際の値</param>
        /// <param name="expected">期待する値</param>
        /// <param name="testName">テスト項目名</param>
        private void CheckFloat(
            float actual,
            float expected,
            string testName)
        {
            Check(
                Mathf.Abs(actual - expected) <= Tolerance,
                $"{testName} " +
                $"(実際：{actual:F3} / 期待：{expected:F3})");
        }

        /// <summary>
        /// 指定された例外が発生することを検証する。
        /// </summary>
        /// <typeparam name="TException">期待する例外型</typeparam>
        /// <param name="action">検証対象の処理</param>
        /// <param name="testName">テスト項目名</param>
        private void CheckThrows<TException>(
            Action action,
            string testName)
            where TException : Exception
        {
            try
            {
                action();

                Check(false, testName);
            }
            catch (TException)
            {
                Check(true, testName);
            }
            catch (Exception exception)
            {
                Check(
                    false,
                    $"{testName}：" +
                    $"想定外の例外 {exception.GetType().Name}");
            }
        }

        #endregion
    }
}
